import json, copy, sys

KIT = '/home/ubuntu/btb/wt3'
calc = json.load(open(KIT + '/out/w3-A.calc.json'))
BASE = 'https://freya-bank-mock.freyavoice.workers.dev/v1'
BLOCK_URL = 'https://example.com/freya-blocked'
HOLS = "['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']"

# ---------------------------------------------------------------- hooks
COMMON = '''
import json, datetime, re
HOLS_A = set(''' + HOLS + ''')
def a_is_bd(d):
    return d.weekday() < 5 and d.isoformat() not in HOLS_A
def a_next_bd(d):
    d = d + datetime.timedelta(days=1)
    for _ in range(30):
        if a_is_bd(d):
            return d
        d = d + datetime.timedelta(days=1)
    return d
def a_today():
    s = str(vars.get('now') or '')[:10]
    return datetime.date.fromisoformat(s)
WDN = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
'''

ACCOUNT_APPEND = COMMON + '''
try:
    if isinstance(result, dict):
        data = result.get('data')
        prods = data.get('products') if isinstance(data, dict) else None
        if isinstance(prods, list):
            t = a_today()
            one = datetime.timedelta(days=1)
            def last_bd_week(start_monday, lo):
                x = start_monday + datetime.timedelta(days=6)
                while x >= lo and not a_is_bd(x):
                    x = x - one
                return x if x >= lo else None
            mon = t - datetime.timedelta(days=t.weekday())
            a1 = last_bd_week(mon, t)
            if a1 is None or a1 == t:
                a1 = last_bd_week(mon + datetime.timedelta(days=7), mon + datetime.timedelta(days=7))
            keep = []
            lines = []
            for p in prods:
                if not isinstance(p, dict):
                    continue
                ty = str(p.get('type'))
                if ty == 'credit_card':
                    p['product_name'] = 'credit card ending ' + str(p.get('card_last4') or '')
                elif ty == 'personal_loan':
                    p['product_name'] = 'personal loan'
                elif ty == 'car_loan':
                    p['product_name'] = 'car loan'
                else:
                    p['product_name'] = ty.replace('_', ' ')
                if a1 is not None:
                    if p.get('deadline') and a1.isoformat() > str(p.get('deadline')):
                        a1p = datetime.date.fromisoformat(str(p.get('deadline')))
                    else:
                        a1p = a1
                    p['attempt_1_date'] = a1p.isoformat()
                    p['attempt_1_date_weekday'] = WDN[a1p.weekday()]
                    p['attempt_1_offer'] = 'the full past_due amount (or floor_amount if the customer already said the full amount is too much) by ' + WDN[a1p.weekday()] + ' ' + a1p.isoformat()
                if str(p.get('band')) == 'late':
                    p['attempt_2_offer'] = 'floor_amount ' + str(p.get('floor_amount')) + ' on the deadline ' + str(p.get('deadline_weekday', '')) + ' ' + str(p.get('deadline'))
                else:
                    p['attempt_2_offer'] = 'none: this band has only one persuasion attempt'
                keep.append(p)
                lines.append('product_id ' + str(p.get('product_id')) + ': ' + str(p.get('product_name')) + ', past_due ' + str(p.get('past_due')) +
                             ', days_late ' + str(p.get('days_late')) + ', band ' + str(p.get('band')) + ', floor_amount ' + str(p.get('floor_amount')) +
                             ', deadline ' + str(p.get('deadline_weekday', '')) + ' ' + str(p.get('deadline')) +
                             ', persuasion_attempts ' + str(p.get('persuasion_attempts')) +
                             ', attempt 1 = ' + str(p.get('attempt_1_offer')) + ', attempt 2 = ' + str(p.get('attempt_2_offer')))
            vars['acct_products_json'] = json.dumps(keep)
            vars['account_summary'] = '\\n'.join(lines)
            data['what_to_do_next'] = ('Now state the debt: say you are calling from the collections team about a late payment, name the product by its product_name, '
                                       'state the past_due amount and the days_late. Then ask exactly: "Can you make this payment today?" '
                                       'Use each product deadline and floor_amount exactly as given here. Never compute them.')
        elif isinstance(data, dict) and data.get('ok') is False:
            data['what_to_do_next'] = 'The account could not be read. Call get_account once more. If it fails again, say you cannot access the account details right now, thank the customer, say goodbye and call close_call with outcome no_promise and reason service_error.'
except Exception:
    pass
'''

VERIFY_PRE = '''
import re, datetime
MONTHS = ['january','february','march','april','may','june','july','august','september','october','november','december']
try:
    b = config.get('body') if isinstance(config, dict) else None
    if isinstance(b, dict):
        f = str(b.get('field') or '')
        a = str(b.get('answer') or '').strip()
        if f == 'phone_last4':
            dg = re.sub(r'[^0-9]', '', a)
            if len(dg) >= 4:
                b['answer'] = dg[-4:]
        elif f == 'date_of_birth':
            out = None
            m = re.match(r'^\\s*(\\d{4})-(\\d{1,2})-(\\d{1,2})\\s*$', a)
            if m:
                out = (int(m.group(1)), int(m.group(2)), int(m.group(3)))
            else:
                m = re.match(r'^\\s*(\\d{1,2})[./ -](\\d{1,2})[./ -](\\d{4})\\s*$', a)
                if m:
                    out = (int(m.group(3)), int(m.group(2)), int(m.group(1)))
                else:
                    low = a.lower()
                    mon = None
                    for i, nm in enumerate(MONTHS):
                        if nm in low or (len(low) >= 3 and re.search(r'\\b' + nm[:3] + r'\\b', low)):
                            mon = i + 1
                            break
                    nums = re.findall(r'\\d+', low)
                    yr = [n for n in nums if len(n) == 4]
                    dy = [n for n in nums if 1 <= len(n) <= 2]
                    if mon and yr and dy:
                        out = (int(yr[0]), mon, int(dy[0]))
            if out:
                try:
                    b['answer'] = datetime.date(out[0], out[1], out[2]).isoformat()
                except Exception:
                    pass
except Exception:
    pass
'''

VERIFY_POST = '''
try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if not isinstance(d, dict):
            d = {'ok': False, 'error': 'service failed'}
            result['data'] = d
        def tb(v):
            return v is True or str(v).lower() == 'true'
        if tb(d.get('all_verified')):
            d['what_to_do_next'] = 'Both answers are verified. Identity check passed.'
        elif d.get('hint') == 'day_month_swapped':
            d['what_to_do_next'] = 'Day and month look swapped. This does NOT count as a wrong answer. Ask the customer to say their date of birth again with the month as a word, for example "the 14th of March".'
        elif not tb(d.get('ok')):
            d['what_to_do_next'] = 'The answer could not be checked (not counted as wrong). If the date was not sent as YYYY-MM-DD, convert it and call verify_identity again. Otherwise ask the customer to repeat the answer.'
        elif tb(d.get('verified')):
            d['what_to_do_next'] = 'This answer is correct. Now ask the security question that has not been passed yet (date of birth first, then the last four digits of the phone number on file).'
        else:
            left = d.get('wrong_answers_left')
            try:
                left = int(left)
            except Exception:
                left = None
            if left is not None and left <= 0:
                d['what_to_do_next'] = 'Third wrong answer: the identity check has ended. Do not state anything about the account.'
            else:
                d['what_to_do_next'] = 'That answer is wrong. Do not reveal the correct answer. Say it does not match our records and ask the SAME question once more.'
except Exception:
    pass
'''

PROMISE_PRE = COMMON + '''
try:
    vars['cp_block'] = ''
    b = config.get('body') if isinstance(config, dict) else None
    raw = vars.get('acct_products_json')
    if isinstance(b, dict):
        try:
            b['amount'] = round(float(str(b.get('amount')).replace(',', '').strip()), 2)
        except Exception:
            pass
        prods = json.loads(raw) if raw else []
        pid = str(b.get('product_id') or '')
        p = None
        for q in prods:
            if str(q.get('product_id')) == pid:
                p = q
        if p is None and len(prods) == 1:
            p = prods[0]
            b['product_id'] = p.get('product_id')
        vars['cp_last_pid'] = str(b.get('product_id') or '')
        probs = []
        done = [x for x in str(vars.get('promised_products') or '').split(',') if x]
        if p is not None:
            if str(p.get('product_id')) in done:
                probs.append('A promise for this product is already recorded in this call. It cannot be changed or cancelled now; the customer can change it in the mobile app.')
            try:
                amt = float(b.get('amount'))
                fl = p.get('floor_amount')
                pdue = p.get('past_due')
                if fl is not None and amt < float(fl) - 0.005:
                    probs.append('The amount ' + str(amt) + ' is below the floor ' + str(fl) + ' and cannot be recorded. Offer the floor ' + str(fl) + ' once.')
                if pdue is not None and amt > float(pdue) + 0.005:
                    probs.append('The amount ' + str(amt) + ' is more than the past-due amount ' + str(pdue) + '. The most you can record is ' + str(pdue) + '.')
            except Exception:
                probs.append('The amount must be a number.')
            try:
                dd = datetime.date.fromisoformat(str(b.get('date') or '').strip()[:10])
                t = a_today()
                dl = p.get('deadline')
                if dd < t:
                    probs.append('The date ' + dd.isoformat() + ' is in the past. Today is ' + WDN[t.weekday()] + ' ' + t.isoformat() + '.')
                elif dl and dd.isoformat() > str(dl):
                    probs.append('The date ' + WDN[dd.weekday()] + ' ' + dd.isoformat() + ' is after the deadline. The latest date you can record is the deadline ' + str(p.get('deadline_weekday', '')) + ' ' + str(dl) + '; offer it.')
                elif not a_is_bd(dd):
                    probs.append('The date ' + WDN[dd.weekday()] + ' ' + dd.isoformat() + ' is not a business day. Offer the next business day, ' + WDN[a_next_bd(dd).weekday()] + ' ' + a_next_bd(dd).isoformat() + '.')
            except Exception:
                probs.append('The date must be sent as YYYY-MM-DD.')
        if probs:
            vars['cp_block'] = ' '.join(probs)
            config['url'] = ''' + repr(BLOCK_URL) + '''
            config['method'] = 'GET'
            config.pop('body', None)
except Exception:
    pass
'''

PROMISE_POST = '''
try:
    if isinstance(result, dict):
        result.pop('header', None)
        blk = str(vars.get('cp_block') or '')
        if blk:
            result['status'] = 'error'
            result['data'] = {'ok': False, 'error': 'NOT RECORDED. ' + blk,
                              'what_to_do_next': 'Nothing was recorded. This was not a service failure, so do not retry the same values. Explain to the customer in one sentence and make the corrected offer from the error, then read it back and ask "Do you confirm?" before calling create_promise again.'}
            vars['cp_block'] = ''
        else:
            d = result.get('data')
            okv = isinstance(d, dict) and (d.get('ok') is True or str(d.get('ok')).lower() == 'true')
            if okv:
                pid = str(vars.get('cp_last_pid') or '')
                done = [x for x in str(vars.get('promised_products') or '').split(',') if x]
                if pid and pid not in done:
                    done.append(pid)
