# ---------------------------------------------------------------- tool builders
def api_tool(name, path, desc, body_props, required, pre='', post='', mapping=None, retries=0):
    props = {'customer_id': {'type': 'string', 'default': '{{customer_id}}'}}
    props.update(body_props)
    t = {
        'type': 'function',
        'config': {'timeoutMs': 15000, 'maxRetries': retries},
        'function': {
            'name': name, 'handler': '__function__:api_call', 'description': desc,
            'parameters': {'type': 'object', 'properties': {
                'url': {'type': 'string', 'default': BASE + path},
                'method': {'type': 'string', 'default': 'POST'},
                'headers': {'type': 'object', 'properties': {'Content-Type': {'type': 'string', 'default': 'application/json'}}},
                'body': {'type': 'object', 'properties': props, 'required': required},
            }},
        },
    }
    if pre: t['pre_process_code'] = pre
    if post: t['post_process_code'] = post
    if mapping: t['response_mapping'] = mapping
    return t

ALL_REASONS = ['none', 'callback', 'no_callback', 'wrong_number', 'deceased', 'unclear', 'failed', 'declined',
               'refused', 'hardship', 'dispute', 'service_error', 'restructuring', 'human', 'support']

