def close_tool(outcomes, reasons, table):
    return api_tool('close_call', '/close_call',
        'Record how the call ended. CALL it exactly once, as the last action of the call, in the same reply as your thank-you and goodbye. Allowed here: ' + table,
        {'outcome': {'type': 'string', 'enum': outcomes, 'default': '{{outcome}}', 'description': 'Call outcome. One of: ' + ', '.join(outcomes)},
         'reason': {'type': 'string', 'enum': reasons, 'default': '{{reason}}', 'description': 'Reason for the outcome. One of: ' + ', '.join(reasons) + '. Use none for promise and paid.'}},
        ['outcome', 'reason'], pre=CLOSE_PRE, post=CLOSE_POST)

