    "- \"I already paid\" (this past-due amount): say payments can take one business day to appear, take no promise, thank them, say goodbye and close_call paid.\n"
    "- \"This debt is not mine\", \"I never had this product\", or the product was closed or paid off in the past: do not argue, take no promise, close_call no_promise / dispute.\n"
    "- A request for a new payment plan or lower instalments: do not describe any plan; call transfer_to_agent with queue restructuring, then close_call transferred / restructuring.\n"
    "- A request for a human: ask once whether you can help first. If they insist, call transfer_to_agent with queue general, then close_call transferred / human.\n"
    "- They say a second time that they do not want to talk: close_call no_promise / refused.\n"
    "- After a recorded promise followed by a transfer, close as transferred with that transfer's reason.\n\n"
    + DATE_RULE
)

# ---------------------------------------------------------------- nodes
def conv(name, task, tools, transitions, on_enter=None, first_only=False, max_turns=60):
    n = {
        'name': name, 'node_type': 'conversation', 'task_message': task, 'tools': tools,
        'transitions': transitions, 'extraction_schema': [], 'max_node_turns': max_turns,
        'truncation_strategy': 'keep_all', 'on_enter_first_entry_only': first_only,
    }
    n['on_enter'] = on_enter or {'type': 'llm'}
    return n

def var_or(target, desc, conds):
    return {'target_node': target, 'description': desc, 'condition': {'logic': 'or', 'conditions': conds}}

def booltest(var):
    return [{'variable': var, 'operator': 'equals', 'operand': 'true'}, {'variable': var, 'operator': 'equals', 'operand': 'True'}]

TO_END = var_or('end_call', 'close_call was called', [
