  for i in range(3):
    try:
      b={'workflowId':W,'message':m}
      if cid: b['callId']=cid
      if cv: b['customerVariables']=cv
      return freya.api('POST','/api/v2/chat/message',b)
    except Exception as e: print('retry',str(e)[:80]); time.sleep(15)
